    /// The least height of a button whose label is two lines (DECISIONS 154). Compact steps it down to 5xl.
    public static let control6xl: Double = 64
    /// The plate of a Menu, Select or Combobox row (the command menu's is size-control-xl, 40). The row is 4px taller: each row carries 2px above and below its plate, so the 4px gap between plates is drawn inside the rows and neighbouring hit areas touch. Compact steps it down to 32.
    public static let menuRow: Double = 36
    /// The least height of a row's hit area on a coarse pointer.
    public static let menuRowTouch: Double = 44
    public static let tapMin: Double = 44
    public static let iconSm: Double = 16
    public static let iconMd: Double = 20
    public static let iconLg: Double = 24
    public static let focusWidth: Double = 2
    public static let focusOffset: Double = 2
    public static let hairline: Double = 1
    /// The underline of the active tab in a horizontal tab bar. There is no vertical bar anywhere: the active row, a selected table row and vertical tabs take a plate, a wash or a pill instead.
    public static let indicator: Double = 2
    /// The label column of a DescriptionList: fixed, never sized to its longest label, so every list on a page shares one value edge and a long label wraps inside it.
    public static let descriptionLabel: Double = 160
    /// The track of Progress and Slider.
    public static let track: Double = 4
    /// Status dots and the radio's checked dot.
    public static let dot: Double = 6
    /// Checkbox and radio box size.
    public static let choice: Double = 16
    /// The check glyph inside a checkbox.
    public static let choiceMark: Double = 12
    /// Switch track width.
    public static let switchWidth: Double = 32
    /// Switch track height.
    public static let switchHeight: Double = 18
    /// Switch thumb diameter.
    public static let switchThumb: Double = 14
    /// Keyboard-key height, everywhere a Kbd appears.
    public static let kbd: Double = 20
    /// Badge height.
    public static let badge: Double = 22
    /// Default table row height; compact and touch densities override it.
    public static let tableRow: Double = 40
    /// The command menu's search row.
    public static let commandInput: Double = 48
    /// Line height of code blocks, independent of body text.
    public static let codeLineHeight: Double = 20
    /// Link underline offset: fixed, so it sits the same under every link.
    public static let underlineOffset: Double = 3
    /// Default length of a vertical slider; apps can override it.
    public static let sliderLength: Double = 180
    /// Dialog width, capped by the viewport.
    public static let dialogWidth: Double = 480
    /// Side sheet width, capped by the viewport.
    public static let sheetWidth: Double = 440
    /// Command menu width, capped by the viewport.
    public static let commandWidth: Double = 560
    /// Toast width, capped by the viewport.
    public static let toastWidth: Double = 360
    /// Popover maximum width.
    public static let popoverMax: Double = 320
    /// Tooltip maximum width.
    public static let tooltipMax: Double = 280
    /// Menu minimum width.
    public static let menuMin: Double = 200
    /// Select trigger minimum width.
    public static let selectMin: Double = 160
    /// Maximum height of a scrolling popup list, such as the command list.
    public static let popupMaxHeight: Double = 360
    /// The list column of a list with a preview pane, fixed: a two-line row fits beside a 16px glyph. The pane takes the rest, space-4 away; below this plus that gap plus size-breakpoint-container the pane is pushed instead.
    public static let listWidth: Double = 320
    /// The sticky bar: its border box, with its hairline inside. The top safe area is padding above it, added by the layout CSS.
    public static let header: Double = 56
    /// The phone tab bar, its hairline inside, before the bottom safe area.
    public static let tabBar: Double = 56
    /// The least height of a link row on the page, directory or big (DECISIONS 152, consent row 3): the link itself, with its 1px rule above it outside. Not the header's or the tab bar's role, though the value is the same. A big row in its two-column form takes space-16.
    public static let row: Double = 56
    /// The app sidebar from the large breakpoint; also a page's own aside, so one side-column width serves both.
    public static let sidebarWidth: Double = 256
    /// The rail, from the medium breakpoint to the large.
    public static let railWidth: Double = 72
    /// The inner row, gutters inside: the header's row and a data page. Written 72rem; resolved here at 16 points to the rem (1152).
    public static let pageWidth: Double = 1152
    /// A prose page's text column, on the row's start edge and never centred: about 72 characters of Geist at 16/24. Written 34rem; resolved here at 16 points to the rem (544).
    public static let proseWidth: Double = 544
    /// The row's inline padding. Apps use the derived --basalt-gutter, which steps to size-gutter-narrow under the medium breakpoint.
    public static let gutter: Double = 24
    /// The row's inline padding under the medium breakpoint.
    public static let gutterNarrow: Double = 16
    /// The space between a page's sections from the large breakpoint (1024). Apps use the derived --basalt-section-gap, which steps to size-section-gap-md from 720 to 1023 and size-section-gap-narrow under 720.
    public static let sectionGap: Double = 128
    /// The space between a page's sections from the medium breakpoint (720) to the large.
    public static let sectionGapMd: Double = 96
    /// The space between a page's sections under the medium breakpoint.
    public static let sectionGapNarrow: Double = 64
    /// The widest line of display type, in the headline's own em: about 28 characters of Geist at 600, so a headline is a block and never a strip across the row. In Swift it is the number of ems (13), for a frame's maximum width.
    public static let displayMeasure: Double = 13
    /// Below it: the phone (the tab bar, the menu sheet, the narrow gutter). A media query cannot read a token, so CSS writes this number beside a lint exception that names the token.
    public static let breakpointMd: Double = 720
    /// From it, the sidebar; below it, down to the medium breakpoint, the rail.
    public static let breakpointLg: Double = 1024
    /// A component's own width, in a container query: a description list stacks and a chart goes narrow below it.
    public static let breakpointContainer: Double = 480
    /// A component's own width, in a container query, below which a button's two lines stay two lines: from it up to size-breakpoint-container the label and its note share one line (DECISIONS 154, D11b). A container query cannot read a token, so CSS writes this number beside a lint exception that names the token.
    public static let breakpointContainerSm: Double = 340
    /// A component's own width, in a container query, below which panels stop sharing one seat and a bar of tabs drops from 56 to 48 (DECISIONS 154, X6 and D12). A container query cannot read a token, so CSS writes this number beside a lint exception that names the token.
    public static let breakpointContainerLg: Double = 640
    /// An observed line and the plan stroke in a chart.
    public static let chartLine: Double = 2
    /// A chart marker's diameter, or its side; the diamond has the same area.
    public static let chartMark: Double = 8
    /// The surface-coloured cut between a mark in front and what it crosses: a chart's marker ring and the plan's cut out of a bar, and the meter's tick.
    public static let cut: Double = 2
    /// The pitch of the hatch that marks missing data: 1px lines at 45 degrees, this far apart.
    public static let hatchPitch: Double = 4
    /// The widest a chart bar is; a bar is 60% of its day.
    public static let chartBarMax: Double = 24
    /// The narrowest a chart bar is.
    public static let chartBarMin: Double = 2
    /// The dash of a chart's second series (6 on, size-chart-dash-gap off), and the pitch of the third series' round dots.
    public static let chartDash: Double = 6
    /// The gap in a chart's dashed second series.
    public static let chartDashGap: Double = 4
    /// A chart plot's height at every width.
    public static let chartPlot: Double = 240
    /// The second, shorter plot height: the phase chart's trend. A plot is 240px, or this (DECISIONS 153, vote 11 and consent row 5).
    public static let chartPlotSm: Double = 96
    /// A marks row's height, a default the app can set: one kind of reading across a run of days (DECISIONS 153, consent row 10).
    public static let chartRow: Double = 56
    /// A range meter's marker: a dot, ringed size-cut in the colour of the surface (DECISIONS 153, consent row 14).
    public static let meterMarker: Double = 12
    /// The top of a stage the art keeps quiet for the bar: size-header (56) plus space-6 (24). The top safe area is added by the layout CSS. No pixel of it passes art-quiet-limit, and a stage declares that the product's headroom check passed.
    public static let stageHeadroom: Double = 80
  }

  /// Aspect ratios, width over height: the four a framed picture takes. `photo` is the default.
  public enum Aspect {
    /// 1:1. Tiles and square pictures.
    public static let square: Double = 1
    /// 3:2. Photographs and drawn scenes in the flow. The default.
    public static let photo: Double = 1.5
    /// 16:10. Product screenshots.
    public static let screen: Double = 1.6
    /// 16:9. Video stills and wide figures.
    public static let wide: Double = 1.7778
  }

  /// A step of the type scale: size and line height in points, tracking in em.
  public struct TypeStyle: Sendable, Equatable {
    public let size: Double
    public let lineHeight: Double
    public let tracking: Double
  }

  public enum TypeScale {
    public static let xs = TypeStyle(size: 12, lineHeight: 16, tracking: 0.01)
    public static let sm = TypeStyle(size: 13, lineHeight: 18, tracking: 0)
    public static let base = TypeStyle(size: 14, lineHeight: 20, tracking: 0)
    public static let md = TypeStyle(size: 16, lineHeight: 24, tracking: -0.005)
    public static let lg = TypeStyle(size: 18, lineHeight: 26, tracking: -0.01)
    public static let xl = TypeStyle(size: 20, lineHeight: 28, tracking: -0.015)
    public static let xl2 = TypeStyle(size: 24, lineHeight: 30, tracking: -0.02)
    public static let xl3 = TypeStyle(size: 30, lineHeight: 36, tracking: -0.025)
    public static let xl4 = TypeStyle(size: 40, lineHeight: 44, tracking: -0.03)
    public static let xl5 = TypeStyle(size: 56, lineHeight: 60, tracking: -0.035)
    public static let xl6 = TypeStyle(size: 72, lineHeight: 76, tracking: -0.04)
    public static let xl7 = TypeStyle(size: 96, lineHeight: 96, tracking: -0.045)
    public static let heroNarrow = TypeStyle(size: 44, lineHeight: 48, tracking: -0.03)
    public static let displayNarrow = TypeStyle(size: 36, lineHeight: 40, tracking: -0.025)
  }

  /// Geist's three weights. In-between weights render differently on native, so Basalt uses whole steps.
  public enum Weight: Int, Sendable, CaseIterable {
    case regular = 400
    case medium = 500
    case semibold = 600
  }

  /// Durations in seconds. Exits run at 0.75 of their entry.
  public enum Duration {
    public static let instant: Double = 0
    public static let fast: Double = 0.1
    public static let base: Double = 0.15
    public static let slow: Double = 0.2
    public static let slower: Double = 0.3
    public static let confirm: Double = 1.5
    public static let figure: Double = 0.6
    public static let stagger: Double = 0.022
  }

  /// A cubic Bézier timing curve.
  public struct Curve: Sendable, Equatable {
    public let x1: Double
    public let y1: Double
    public let x2: Double
    public let y2: Double
  }

  /// Timing curves. None overshoots.
  public enum Easing {
    public static let out = Curve(x1: 0.16, y1: 1, x2: 0.3, y2: 1)
    public static let inOut = Curve(x1: 0.65, y1: 0, x2: 0.35, y2: 1)
    public static let `in` = Curve(x1: 0.4, y1: 0, x2: 1, y2: 1)
  }
}
